using namespace std;

long long co(long long n, long long k) {
    if (k < 0 || k > n) return 0;
    k = min(k, n - k);

    __int128 result = 1;
    for (long long i = 1; i <= k; ++i) {
        result = result * (n - k + i) / i;
    }
    return static_cast<long long>(result);
}

